@Article{Dhusia2016, author= {Dhusia, Kalyani
and Kesarwani, Pragya
and Yadav, Pramod Kumar}, title= {Epitope prediction for MSP119 protein in Plasmodium yeolii using computational approaches}, journal= {Network Modeling Analysis in Health Informatics and Bioinformatics}, year= {2016}, month= {Jun}, day= {04}, volume= {5}, number= {1}, pages= {19}, abstract= {Malaria disease is caused by the transmission of Plasmodium, through the bite of a female A                        nopheles mosquito. Although the Plasmodium life-cycle has been extensively characterized, relatively little is known about sporozoite interaction with host organelles and proteins. Individuals that survive continuous exposure to infection do eventually develop clinical immunity, suggesting that a vaccine against asexual blood stage of the parasite is achievable. The merozoite surface protein (MSP119) of Plasmodium yoelii was considered as the target protein for epitope prediction using the computational approaches. The T-cell and B-cell epitopes for MSP119 were predicted using a variety of computational tools. Out of these predicted epitopes, the epitopes being expressed by the protozoa were identified. The 3D structures of T-cell epitopes (MHC-I and MHC-II) were modeled by homology modeling method followed by validation using the SAVES server. Further, the MHC molecules were identified and their 3D structures were retrieved from the Protein Data Bank. The protein--protein docking of modeled epitopes with respective MHC molecules were also carried out. Total Six T-cell epitopes (`ELSEHYYDRY', `LLIITIVFNI', `MMYHIYKLK', `IYQAMYNVIF', `SEEDMPADDF', `YVLLQNSTI') for MSP119 have been identified as promising vaccine candidates. Furthermore, six B-cell epitopes (`QPTET', `SEETE', `SDKYNKKKP', `KEKKKE', `CKKNKA', `THPDNT') have also been identified as potential epitopes. In future, these predicted epitopes might be exploited in vaccine development against malarial infection.}, issn= {2192-6670}, doi= {10.1007/s13721-016-0127-4}, url= {https://doi.org/10.1007/s13721-016-0127-4}}
